/// <summary>
/// This class contains the extension function for the <c>LedgerJournalTrans</c> table.
/// </summary>
[ExtensionOf(tableStr(LedgerJournalTrans))]
public final class METLedgerJournalTrans_Extension
{

}

Method.Source:
    /// <summary>
    /// Get journal number from Open vendor transactions.
    /// </summary>
    /// <returns>Journal number</returns>
    public LedgerJournalId getMETVendOpenTransJournalNum()
    {
        VendTrans       vendTrans;
        VendTransOpen   vendTransOpen;
        SpecTrans       specTrans;
        
        if (this.RecId > 0)
        {
            select firstonly JournalNum from vendTrans
                exists join vendTransOpen
                    where vendTransOpen.RefRecId == vendTrans.RecId
                exists join specTrans
                    where specTrans.RefCompany   == vendTransOpen.DataAreaId
                       && specTrans.RefTableId   == vendTransOpen.TableId
                       && specTrans.RefRecId     == vendTransOpen.RecId
                       && specTrans.SpecCompany  == this.DataAreaId
                       && specTrans.SpecRecId    == this.RecId
                       && specTrans.SpecTableId  == this.TableId;
        }

        return vendTrans.journalNum;
    }

    /// <summary>
    /// Get invoice number from Open customer transactions.
    /// </summary>
    /// <returns>Invoice number</returns>
    public InvoiceId getMETCustOpenTransInvoiceNum()
    {
        CustTrans       custTrans;
        CustTransOpen   custTransOpen;
        SpecTrans       specTrans;
        
        if (this.RecId > 0)
        {
            select firstonly Invoice from custTrans
                exists join custTransOpen
                    where custTransOpen.RefRecId == custTrans.RecId
                exists join specTrans
                    where specTrans.RefCompany   == custTransOpen.DataAreaId
                       && specTrans.RefTableId   == custTransOpen.TableId
                       && specTrans.RefRecId     == custTransOpen.RecId
                       && specTrans.SpecCompany  == this.DataAreaId
                       && specTrans.SpecRecId    == this.RecId
                       && specTrans.SpecTableId  == this.TableId;
        }

        return custTrans.Invoice;
    }

    /// <summary>
    /// MPJ_3338_AMEXCustomerPaymentProcessing - Vpotula
    /// Finds the <c>METCustTable</c> record corresponding to the account.
    /// </summary>
    /// <returns>
    /// A record from the <c>METCustTable</c> table; otherwise, an empty record.
    /// </returns>
    /// <exception cref="M:Exception::Error">
    /// The account company does not exist.
    /// </exception>
    public METCustTable findMETCustTable()
    {
        METCustTable metCust;

        if (this.isCompanyIntercompany())
        {
            if (!xDataArea::exist(this.Company))
            {
                throw error(strFmt("@SYS10666", this.Company));
            }

            metCust = METCustTable::findByCompany(this.Company, this.parmAccount());
        }
        else
        {
            metCust = METCustTable::findByLedgerDimension(this.LedgerDimension);
        }

        return metCust;
    }

    public void insert()
    {
        this.setOffsetAcc();
        this.setDefaultDimension();
        
        next insert();

    }

    public void update()
    {
        this.setOffsetAcc();
        this.setDefaultDimension();

        next update();
    }

    public void setOffsetAcc()
    {
        LedgerJournalTable  ledgerJournalTable;
        CustAccount custAcc;
        VendTable   vendTable;

        ledgerJournalTable = this.ledgerJournalTable();

        if (ledgerJournalTable.JournalType == LedgerJournalType::CustPayment)
        {
            if (this.OffsetLedgerDimension == 0 &&
                this.OffsetAccountType == LedgerJournalACType::Vend &&
                this.PaymMode == METConstants::NettingPaymMode)
            {
                changecompany(this.Company)
                {
                    custAcc = LedgerDimensionFacade::getDisplayValueForLedgerDimension(this.LedgerDimension);
                    vendTable = VendTable::find(custTable::find(custAcc).VendAccount);

                    this.OffsetLedgerDimension = LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(vendTable.AccountNum, LedgerJournalACType::Vend);
                    if (vendTable.DefaultDimension != 0)
                    {
                        this.OffsetDefaultDimension = vendTable.defaultDimension;
                    }
                    else
                    {
                        this.OffsetDefaultDimension = this.DefaultDimension;
                    }
                }
            }
        }
    }

    public void setDefaultDimension()
    {
        LedgerJournalTable  metLedgerJournalTable  = LedgerJournalTable::find(this.JournalNum);
        LedgerJournalName   metLedgerJournalName   = LedgerJournalName::find(metLedgerJournalTable.journalname);

        if (metLedgerJournalName.METFreezeDefaultDimensions == NoYes::Yes && this.AccountType == LedgerJournalACType::Vend)
        {
            this.DefaultDimension = metLedgerJournalTable.DefaultDimension;
        }

    }

    /// <summary>
    /// Kurt Scerri - 03/03/2021
    /// method to table level to calculate the tax amount curr
    /// Calculates RebGst according to the record
    /// </summary>
    /// <returns>RebGST</returns>
    public TaxAmountJournal METTaxAmountJournal()
    {
        TaxAmountJournal   taxAmountCur = 0;

        taxAmountCur = Tax::taxTotalVoucherDateRecId(this.Voucher, this.TransDate, this.RecId);

        return taxAmountCur;
    }

    /// <summary>
    /// validates data before writing code
    /// </summary>
    /// <returns>boolean</returns>
    public boolean validateWrite()
    {
        boolean             ret = true;
        LedgerJournalTable  journalHeader, ledgerJournalTable, ledgerJournalTableHistorical;
        LedgerJournalTrans  ledgerJournalTrans, ledgerJournalTransHistorical;
        LedgerJournalEntityStaging  staging;
        DimensionAttributeValueCombination  dimensionAttributeValueCombination;

        CustTrans           custTrans;
        CustParameters      custParameters = custParameters::find();
        boolean             isHistoricalInvoiceExist = false;

        next validateWrite();
        
        journalHeader = this.ledgerJournalTable(); 

        if (journalHeader)
        {
            if (journalHeader.Name like "@MET:JornlHdr")
            {
                select firstonly JournalNum, Txt, DocumentNum from ledgerJournalTrans
                    where ledgerJournalTrans.Txt        == this.Txt 
                    &&    ledgerJournalTrans.RecId      != this.Recid
                    &&    ledgerJournalTrans.JournalNum != journalHeader.JournalNum;
            }
            
            if (journalHeader.Name like "@MET:JornlHdr" || journalHeader.Name like "@MET:JornlHdr")
            {
                select firstonly JournalNum, Voucher, DocumentNum from ledgerJournalTrans
                    where ledgerJournalTrans.Voucher    == this.Voucher
                    &&    ledgerJournalTrans.RecId      != this.RecId
                    &&    ledgerJournalTrans.JournalNum != journalHeader.JournalNum;
            }

            if(curExt() == '@MET:MET2002')
            {
                isHistoricalInvoiceExist = true;

                if((custParameters.METAR67RestrictDuplicateInvoiceCheck 
                    && (journalHeader.JournalName == '@MET:CustInv' || journalHeader.JournalName == '@MET:CustInvMC' 
                    || journalHeader.JournalName == '@MET:CustInvDC') // || journalHeader.JournalName == 'CustInv') 
                    && (this.AccountType == LedgerJournalACType::Cust || this.AccountType == LedgerJournalACType::Ledger)))
                {
                    select firstonly AccountDisplayValue, ExecutionId from staging
                        order by staging.JournalBatchNumber desc
                        where staging.Invoice == this.Invoice 
                        && staging.Document == this.DocumentNum
                        && staging.AccountType == LedgerJournalACType::Cust
                        && (staging.JournalName == '@MET:CustInv' || staging.JournalName == '@MET:CustInvMC'
                        || staging.JournalName == '@MET:CustInvDC') //|| staging.JournalName == 'CustInv')
                        && staging.METCompany  == '@MET:MET2002';

                    select firstonly Invoice,RecId, METExecutionId,METJournalName from ledgerJournalTrans join
                            dimensionAttributeValueCombination
                            order by ledgerJournalTrans.JournalNum desc
                        where (this.Invoice !='' && ledgerJournalTrans.Invoice  == this.Invoice)
                            && ledgerJournalTrans.AccountType == LedgerJournalACType::Cust
                            && dimensionAttributeValueCombination.RecId == ledgerJournalTrans.LedgerDimension
                        && dimensionAttributeValueCombination.DisplayValue == staging.AccountDisplayValue;
                            
                                
                        // Default value - isHistoricalInvoiceExist = TRUE
                        if(ledgerJournalTrans.recId) 
                            isHistoricalInvoiceExist = false;
                        if(ledgerJournalTrans.METExecutionId !='' && ledgerJournalTrans.METExecutionId == staging.ExecutionId
                            && (ledgerJournalTrans.METJournalName == '@MET:CustInv' || ledgerJournalTrans.METJournalName == '@MET:CustInvMC'
                            || ledgerJournalTrans.METJournalName == '@MET:CustInvDC')) //|| ledgerJournalTrans.METJournalName == 'CustInv'))  
                            isHistoricalInvoiceExist = true;
                }

                // For AP-68
                if((VendParameters::find().METAP68RestrictDuplicateInvoiceCheck
                    && (journalHeader.JournalName == 'VenInvNZ') 
                    && (this.AccountType == LedgerJournalACType::Vend || this.AccountType == LedgerJournalACType::Ledger)))
                {
                    select firstonly AccountDisplayValue, ExecutionId from staging
                        order by staging.JournalBatchNumber desc
                        where staging.Invoice == this.Invoice
                        && staging.Document == this.DocumentNum
                        && staging.AccountType == LedgerJournalACType::Vend
                        && staging.JournalName == 'VenInvNZ'
                        && staging.METCompany  == '@MET:MET2002';

                    select firstonly RecId, METExecutionId,METJournalName from ledgerJournalTrans join
                            dimensionAttributeValueCombination
                            order by ledgerJournalTrans.JournalNum desc
                        where (this.Invoice !='' && ledgerJournalTrans.Invoice  == this.Invoice)
                            && ledgerJournalTrans.AccountType == LedgerJournalACType::Vend
                            && dimensionAttributeValueCombination.RecId == ledgerJournalTrans.LedgerDimension
                        && dimensionAttributeValueCombination.DisplayValue == staging.AccountDisplayValue;
                            
                                
                    // Default value - isHistoricalInvoiceExist = TRUE
                    if(ledgerJournalTrans.recId)
                        isHistoricalInvoiceExist = false;
                    if(ledgerJournalTrans.METExecutionId !='' && ledgerJournalTrans.METExecutionId == staging.ExecutionId
                        && ledgerJournalTrans.METJournalName == 'VenInvNZ')
                        isHistoricalInvoiceExist = true;
                }

                // For GL-70
                if(LedgerParameters::find().METGL70RestrictDuplicateInvoiceCheck
                        && (journalHeader.JournalName == '@MET:GLINT')// || journalHeader.JournalName ==   'GLGenJrn') 
                        && this.AccountType == LedgerJournalACType::Ledger)
                {
                    LedgerjournalTable   ledgerjournalTableForGL70;

                    select firstonly Document, ExecutionId from staging
                        order by staging.JournalBatchNumber desc
                        where staging.Document == this.DocumentNum
                        && staging.AccountType == LedgerJournalACType::Ledger
                        && (staging.JournalName == '@MET:GLINT')// || journalHeader.JournalName ==   'GLGenJrn') 
                        && staging.METCompany  == '@MET:MET2002';

                    select firstonly RecId, METExecutionId,METJournalName from ledgerJournalTrans join ledgerjournalTableForGL70
                            order by ledgerJournalTrans.JournalNum desc
                        where (this.DocumentNum !='' && ledgerJournalTrans.DocumentNum  == staging.Document)
                            && ledgerJournalTrans.AccountType == LedgerJournalACType::Ledger
                            && ledgerJournalTrans.JournalNum  == ledgerjournalTableForGL70.JournalNum
                            && (ledgerjournalTableForGL70.JournalName == '@MET:GLINT' 
                            || ledgerjournalTableForGL70.JournalName ==   'GLGenJrn');
                                
                    // Default value - isHistoricalInvoiceExist = TRUE
                    if(ledgerJournalTrans.recId)
                        isHistoricalInvoiceExist = false;
                    if(ledgerJournalTrans.METExecutionId !='' && ledgerJournalTrans.METExecutionId == staging.ExecutionId
                        && (ledgerJournalTrans.METJournalName == '@MET:GLINT'))// || journalHeader.JournalName ==   'GLGenJrn')) 
                        isHistoricalInvoiceExist = true;
                }
            }
        }

        if (ledgerJournalTrans && !isHistoricalInvoiceExist)
        {
            ret = checkFailed(strFmt("@MET:Vouch1RefJrnlNumWarn",this.voucher, ledgerJournalTrans.JournalNum));
        }
            
        return ret;
    }

    /// <summary>
    /// Return error description.
    /// </summary>
    /// <returns>Error code description</returns>
    public display Description255 metErrorCodeDescription()
    {
        BankReturnFormatErrorCodes_W returnCode;
        select firstonly Description from returnCode
                    where returnCode.Code == this.ErrorCodePayment;

        return ReturnCode.description;
    }

    /// <summary>
    /// Validate delete
    /// </summary>
    /// <returns>true/false</returns>
    public boolean validateDelete()
    {
        boolean ret = true;

        ret =  next validateDelete();

        
        if (this.metValidatePaymentStatus())
        {
            ret = METPaymentControl::newFromledgerJournalTrans(this, METRecordAction::Delete).validateAction();
        }

        return ret;
    }

/// <summary>
/// Check if the payment status can be validated
/// </summary>
/// <returns>true/false.</returns>
public boolean metValidatePaymentStatus()
{
    return VendPaymModeTable::find(this.PaymMode).METValidatePaymentStatus;
}

/// <summary>
/// Determines whether edit  should be considered based on metpay payment status.
/// </summary>
/// <returns>true if allow edit should be considered; otherwise, false.</returns>
public boolean metAllowEditBasedOnPaymentStatus()
{
    return (this.PaymentStatus == CustVendPaymStatus::METDueDateSent ||
            this.PaymentStatus == CustVendPaymStatus::METResendSent ||
            this.PaymentStatus == CustVendPaymStatus::METWithdrawSent ||
            this.PaymentStatus == CustVendPaymStatus::METDueDateUpdated ||
            this.PaymentStatus == CustVendPaymStatus::METResent ||
            this.PaymentStatus == CustVendPaymStatus::METWithdrawn);
}

/// <summary>
/// Determines whether delete  should be considered based on metpay payment status.
/// </summary>
/// <returns>true if allow delete should be considered; otherwise, false.</returns>
public boolean metAllowDeleteBasedOnPaymentStatus()
{
    return METPaymentControl::newFromledgerJournalTrans(this, METRecordAction::Delete).validateAction();
}

/// <summary>
/// Check if the payment mode is metpay
/// </summary>
/// <returns>true if metpay; otherwise false.</returns>
public boolean metIsMetPay()
{
    return this.PaymMode == VendParameters::find().METPayPaymMode;
}

    /// <summary>
    /// Validate Write LedgerJournalTrans extension
    /// </summary>
    /// <param name="sender">Table buffer record</param>
    /// <param name="e">Data Event arguments</param>
    [DataEventHandler(tableStr(LedgerJournalTrans), DataEventType::ValidatedWrite)]
    public static void LedgerJournalTrans_onValidatedWrite(Common sender, DataEventArgs e)
    {
        LedgerJournalTable          ledgerJournalTable;
        NoYesCombo                  paymDate;
        PaymTerm                    paymTerm;
        LedgerJournalEntityStaging  staging;
        //LedgerJournalTrans          ledgerJournalTrans;

        //Retrieve the Ledger Journal Trans Buffer
        LedgerJournalTrans ledgerJournalTrans = sender as ledgerJournalTrans;

        //Retrieve the LedgerJournal Table buffer
        ledgerJournalTable = LedgerJournalTable::find(ledgerJournalTrans.JournalNum);

        //Payment Date Buffer
        paymDate = LedgerJournalName::find(ledgerJournalTable.JournalName).METPaymDate;

        //Payment Term buffer
        paymTerm = PaymTerm::find(ledgerJournalTrans.Payment);

        
        if(ledgerJournalTrans.DataAreaId == '@MET:MET2002')
        {
            if(CustParameters::find().METAR67RestrictDuplicateInvoiceCheck
                && (ledgerJournalTable.JournalName == '@MET:CustInv' || ledgerJournalTable.JournalName == '@MET:CustInvMC'
                || ledgerJournalTable.JournalName == '@MET:CustInvDC')// || ledgerJournalTable.JournalName == 'CustInv') 
                && (ledgerJournalTrans.AccountType == LedgerJournalACType::Cust || ledgerJournalTrans.AccountType == LedgerJournalACType::Ledger))
            {
                select firstonly executionId,JournalName from staging
                                order by staging.JournalBatchNumber desc
                                where staging.Invoice == ledgerJournalTrans.Invoice
                                && staging.Document == ledgerJournalTrans.DocumentNum
                                && staging.AccountType == LedgerJournalACType::Cust
                                && (staging.JournalName == '@MET:CustInv' || staging.JournalName == '@MET:CustInvMC'
                                || staging.JournalName == '@MET:GLINT'
                                || staging.JournalName == '@MET:CustInvDC')
                               // || staging.JournalName == 'CustInv')  
                                && staging.METCompany  == '@MET:MET2002';
                if(staging.ExecutionId !='')
                {
                    ledgerJournalTrans.METExecutionId = staging.ExecutionId;
                    ledgerJournalTrans.METJournalName = staging.JournalName;
                }
            }
            else if(VendParameters::find().METAP68RestrictDuplicateInvoiceCheck
                && (ledgerJournalTable.JournalName == 'VenInvNZ') 
                && (ledgerJournalTrans.AccountType == LedgerJournalACType::Vend || ledgerJournalTrans.AccountType == LedgerJournalACType::Ledger))
            {
                select firstonly executionId,JournalName from staging
                            order by staging.JournalBatchNumber desc
                            where staging.Invoice == ledgerJournalTrans.Invoice
                            && staging.Document == ledgerJournalTrans.DocumentNum
                            && staging.AccountType == LedgerJournalACType::Vend
                            && staging.JournalName == 'VenInvNZ'
                            && staging.METCompany  == '@MET:MET2002';
                if(staging.ExecutionId !='')
                {
                    ledgerJournalTrans.METExecutionId = staging.ExecutionId;
                    ledgerJournalTrans.METJournalName = staging.JournalName;
                }
            }
            else if(LedgerParameters::find().METGL70RestrictDuplicateInvoiceCheck
                && (ledgerJournalTable.JournalName == '@MET:GLINT')// || ledgerJournalTable.JournalName ==  'GLGenJrn') 
                && (ledgerJournalTrans.AccountType == LedgerJournalACType::Ledger))
            {
                select firstonly executionId,JournalName from staging
                            order by staging.JournalBatchNumber desc
                            where staging.Invoice == ledgerJournalTrans.Invoice
                            && staging.Document == ledgerJournalTrans.DocumentNum
                            && staging.AccountType == LedgerJournalACType::Ledger
                            && (staging.JournalName == '@MET:GLINT')// || ledgerJournalTable.JournalName == 'GLGenJrn') 
                            && staging.METCompany  == '@MET:MET2002';
                if(staging.ExecutionId !='')
                {
                    ledgerJournalTrans.METExecutionId = staging.ExecutionId;
                    ledgerJournalTrans.METJournalName = staging.JournalName;
                }
            }
        }

        //Check if the Payment date toggle control is set to Yes
        if(paymDate == NoYesCombo::Yes)
        {
            if(ledgerJournalTrans.Payment && LedgerJournalTrans.Invoice!= '')
            {
                //Payment term due date calculation
                ledgerJournalTrans.Due = paymTerm.due(ledgerJournalTrans.TransDate,paymTerm.PaymDayId);
            }
            else if(ledgerJournalTrans.Payment && ledgerJournalTrans.Invoice == '')
            {
                //Payment term due date calculation
                ledgerJournalTrans.Due = paymTerm.due(ledgerJournalTrans.TransDate,paymTerm.PaymDayId);
            }
        }
    }
